// ===================== SYSTEM TRAY =====================
HICON gAppIcon = NULL; // forward declared here, initialized in loadAppIcon()
NOTIFYICONDATA nid = {};

void addTrayIcon(HWND hwnd) {
    nid.cbSize = sizeof(NOTIFYICONDATA);
    nid.hWnd   = hwnd;
    nid.uID    = ID_TRAY_ICON;
    nid.uFlags = NIF_ICON | NIF_MESSAGE | NIF_TIP;
    nid.uCallbackMessage = WM_TRAYICON;
    nid.hIcon  = gAppIcon ? gAppIcon : LoadIcon(NULL, IDI_APPLICATION);
    wcscpy_s(nid.szTip, L"wrathic");
    Shell_NotifyIcon(NIM_ADD, &nid);
}

void removeTrayIcon() {
    Shell_NotifyIcon(NIM_DELETE, &nid);
}
bool trayIconVisible = false;
void showTrayIcon(HWND hwnd) {
    if (trayIconVisible) return;
    addTrayIcon(hwnd);
    trayIconVisible = true;
}
void hideTrayIcon() {
    if (!trayIconVisible) return;
    removeTrayIcon();
    trayIconVisible = false;
}

