    drawText(hdc,dk2.c_str(),p+14,y+22,cw-106,18,T.text,hFontMono,DT_LEFT|DT_VCENTER|DT_SINGLELINE);
    drawRR(hdc,p+cw-92,y+15,40,20,6,T.btn,T.border,1);
